   164	            };
   165	            results.add(pool.submit(payment));
   166	        }
   167	        start.countDown();
   168	        List<Integer> statuses = new ArrayList<>();
   169	        for (Future<Integer> result : results) {
   170	            statuses.add(result.get());
   171	        }
   172	        pool.shutdown();
   173	
   174	        assertThat(statuses).filteredOn(s -> s == 200).hasSize(1);
   175	        assertThat(statuses).filteredOn(s -> s == 409).hasSize(buyers - 1);
